require __DIR__.'/app/bootstrap.php';$orderId=(int)($_GET['order']??$_POST['order']??0);$token=(string)($_GET['token']??$_POST['token']??'');$s=db()->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$orderId]);$order=$s->fetch();$valid=false;if($order&&$token!==''&&!empty($order['account_claim_token_hash'])&&!empty($order['account_claim_expires_at'])&&strtotime($order['account_claim_expires_at'])>=time())$valid=hash_equals($order['account_claim_token_hash'],hash('sha256',$token));
if($_SERVER['REQUEST_METHOD']==='POST'){
